			function filterList() {
				
				return;
				
				var dsList = app.lookup("dsList");
				
				dsList.clearFilter();
				
				var condition = "";
				
				var dmSearch = app.lookup("dmSearch");
				
				if (dmSearch.getValue("SEARCH_TYPE") == "ID") {
					if (dmSearch.getValue("SEARCH_VALUE") != null && dmSearch.getValue("SEARCH_VALUE") != "") {
						condition = "USER_ID *= '" + dmSearch.getValue("SEARCH_VALUE") + "'";
					}
				} else if (dmSearch.getValue("SEARCH_TYPE") == "NAME") {
					if (dmSearch.getValue("SEARCH_VALUE") != null && dmSearch.getValue("SEARCH_VALUE") != "") {
						condition = "USER_NM *= '" + dmSearch.getValue("SEARCH_VALUE") + "'";
					}
				}
				
				if (dmSearch.getValue("APPLY_START_DATE") != null && dmSearch.getValue("APPLY_START_DATE") != "") {
					if (condition == "") {
						condition = "JOIN_APLY_DT >= '" + dmSearch.getValue("APPLY_START_DATE") + "'";
					} else {
						condition += " and JOIN_APLY_DT >= '" + dmSearch.getValue("APPLY_START_DATE") + "'";
					}
				}
				
				if (dmSearch.getValue("APPLY_END_DATE") != null && dmSearch.getValue("APPLY_END_DATE") != "") {
					if (condition == "") {
						condition = "JOIN_APLY_DT <= '" + dmSearch.getValue("APPLY_END_DATE") + "'";
					} else {
						condition += " and JOIN_APLY_DT <= '" + dmSearch.getValue("APPLY_END_DATE") + "'";
					}
				}
				
				if (dmSearch.getValue("USER_TYPE") != null && dmSearch.getValue("USER_TYPE") != "") {
					if (condition == "") {
						condition = "USER_TYPE == '" + dmSearch.getValue("USER_TYPE") + "'";
					} else {
						condition += " and USER_TYPE == '" + dmSearch.getValue("USER_TYPE") + "'";
					}
				}
				
				if (dmSearch.getValue("USER_ID_USE_SE_CD") != null && dmSearch.getValue("USER_ID_USE_SE_CD") != "") {
					if (condition == "") {
						condition = "USER_ID_USE_SE_CD == '" + dmSearch.getValue("USER_ID_USE_SE_CD") + "'";
					} else {
						condition += " and USER_ID_USE_SE_CD == '" + dmSearch.getValue("USER_ID_USE_SE_CD") + "'";
					}
				}
				
				//console.log("dmSearch", dmSearch);
				//console.log("condition", condition);
				
				if (condition == "") {
				   dsList.clearFilter();
				} else {
				   dsList.setFilter(condition);
				}
			}

